// Android, зона без воды (светлый экран, серая поверхность, бумага, клавиатура, стол): «לא זוהו מים באזור שסומן. כוונו את המצלמה לבריכה וסמנו את שטח המים.»,
// «המשך» серая даже с галочкой «כל שטח המים נראה…»; «זו הבריכה שלי» нет (раньше открывала «המשך» — это и был баг). Красные точки — вручную по скриншоту.
// РУЧНАЯ СЦЕНА (требует подготовки): камера Pixel на экран Mac с картинкой на весь экран: .qa/media/screen-white-bluish.png, .qa/media/surface-grey-cool.png
// или .qa/media/table-brown.png — либо физическая бумага/клавиатура/стол. BANCI_SCENE=no-water-light | no-water (иначе пропуск). Шаг 1 → BANCI_SOUND=1.
// Известная слабость (находка, не реджект, 08.11): насыщенно-циановая поверхность может пройти. Мониторинг НЕ запускается.
import { assert, skip, openCameraStep, checkWaterBox, NO_WATER_HINT, OLD_POOL_CHECKBOX } from '../lib.mjs';

export const name = 'Android шаг 2, светлая поверхность без воды: «לא זוהו מים…», «המשך» серая даже с галочкой, «זו הבריכה שלי» нет (ручная сцена BANCI_SCENE=no-water-light) #ab4270 @android @app';
const NO_WATER = 'לא זוהו מים באזור שסומן. כוונו את המצלמה לבריכה וסמנו את שטח המים.';

export default async function (app) {
  if (!['no-water-light', 'no-water'].includes(process.env.BANCI_SCENE)) skip('ручная сцена: на Mac на весь экран .qa/media/screen-white-bluish.png (или бумага/клавиатура/стол перед камерой) → BANCI_SCENE=no-water-light');

  await openCameraStep(app);
  await app.waitFor(NO_WATER_HINT, { timeout: 20000, what: `подсказка «${NO_WATER}» (нет — проверить сцену)` });
  assert(!(await app.exists(OLD_POOL_CHECKBOX)), 'нет галочки «זו הבריכה שלי» (OTA c38476a1 не загрузился?)');
  await checkWaterBox(app);
  await app.waitEnabled('המשך', false, { timeout: 5000, what: '«המשך» на зоне без воды с галочкой' });
  assert(await app.exists(NO_WATER), 'подсказка «לא זוהו מים…» осталась после галочки');
  await app.screenshot('ab4270-step2-light-no-water-blocked');
  await app.restart();
}
